import math
def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    views = obs.get('views', {})
    v = views.get('direct') or {}
    rails = v.get('walls', [])
    # For this rearward gaze, compare the closest rail points on either side.
    left = []
    right = []
    for b, d in rails:
        if d > 12: continue
        y = math.sin(math.radians(b)) * d
        if y > 0.35: left.append(d)
        elif y < -0.35: right.append(d)
    dl = min(left) if left else 8.0
    dr = min(right) if right else 8.0
    # Positive steering follows a positive hitch swing; add a small bias away from the nearer rail.
    rail_bias = max(-7.0, min(7.0, 3.0 * (dr - dl)))
    steer = max(-14.0, min(14.0, 0.9*h + rail_bias))
    return (steer, -0.18, -160.0)

